  "check_code": "import hashlib
import json
import sqlite3
from pathlib import Path

from openpyxl import load_workbook

try:
    from _helpers import recalc_xlsx, norm_label
except ImportError:
    def recalc_xlsx(path):
        return Path(path)
    def norm_label(value):
        return "" if value is None else " ".join(str(value).strip().lower().split())


ISSUE_KEY = "WEBOPS-1051"
VALIDATION_ID = "VAL-2025-8124"
WORKBOOK_NAME = "NorthstarCommerce_ConnectionPool_CorrectiveActionRegister_2025-09.xlsx"
JIRA_OTHER_DIGEST = "bcb3d000622fc017ae635227c49d60294d575f865b94f9aa361a950b4136d282"
WORKBOOK_OTHER_DIGEST = "d89fbc89cd72d806475220d098d47fd7a8d7b479a7c92dead4cf8c95d2afe126"


def _jira_path(ws):
    return Path(ws).resolve().parent / "system" / "jira_web_operations" / "state.db"


def _query(ws, sql, params=()):
    con = sqlite3.connect(f"file:{_jira_path(ws)}?mode=ro", uri=True)
    con.row_factory = sqlite3.Row
    try:
        return [dict(row) for row in con.execute(sql, tuple(params)).fetchall()]
    finally:
        con.close()


def _workbook(ws):
    return Path(ws) / "02_analysis" / WORKBOOK_NAME


def _header_map(row):
    return {norm_label(value): index + 1 for index, value in enumerate(row) if value is not None}


def _action_row(sheet):
    headers = _header_map([sheet.cell(5, col).value for col in range(1, sheet.max_column + 1)])
    action_col = headers[norm_label("Action ID")]
    for row in range(6, sheet.max_row + 1):
        if norm_label(sheet.cell(row, action_col).value) == norm_label("ACT-004"):
            return row, headers
    return None, headers


def check_jira_reopened(ws):
    issue = _query(ws, "SELECT * FROM corrective_action_issues WHERE issue_key = ?", (ISSUE_KEY,))
    if len(issue) != 1:
        return {"score": 0, "detail": "target Jira issue not found uniquely"}
    row = issue[0]
    if norm_label(row["status"]) != norm_label("In Progress"):
        return {"score": 0, "detail": f"status is {row['status']!r}"}
    history = _query(ws, """SELECT * FROM action_status_history
        WHERE issue_id = ? ORDER BY changed_at_edt DESC, history_id DESC LIMIT 1""", (row["issue_id"],))
    if len(history) != 1:
        return {"score": 0, "detail": "newest history event missing"}
    event = history[0]
    note = norm_label(event["note"])
    valid_note = "notification" in note and ("on-call" in note or "on call" in note or "paging" in note or "page" in note)
    valid_event = (
        norm_label(event["from_status"]) == norm_label("Done")
        and norm_label(event["to_status"]) == norm_label("In Progress")
        and norm_label(event["completion_evidence_ref"]) == norm_label(VALIDATION_ID)
        and valid_note
    )
    if not valid_event:
        return {"score": 0, "detail": "newest event does not reopen the action with the failed validation and routing explanation"}
    validation = _query(ws, "SELECT result FROM release_validation_records WHERE validation_id = ? AND issue_id = ?", (VALIDATION_ID, row["issue_id"]))
    if len(validation) != 1 or norm_label(validation[0]["result"]) != norm_label("Failed"):
        return {"score": 0, "detail": "linked validation is not the failed validation"}
    return {"score": 1, "detail": "WEBOPS-1051 is In Progress with a valid VAL-2025-8124 reopening event"}


def check_workbook_action(ws):
    try:
        path = recalc_xlsx(_workbook(ws))
        book = load_workbook(path, data_only=True)
        sheet = book["Action Register"]
    except Exception as exc:
        return {"score": 0, "detail": f"workbook could not be read: {exc}"}
    row, headers = _action_row(sheet)
    if row is None:
        return {"score": 0, "detail": "ACT-004 not found"}
    status = sheet.cell(row, headers[norm_label("Status")]).value
    result = sheet.cell(row, headers[norm_label("Verification Result")]).value
    note = norm_label(sheet.cell(row, headers[norm_label("Review Note")]).value)
    has_notification_signal = any(term in note for term in ("notification", "alert", "paging"))
    has_route_signal = "route" in note or "routing" in note
    has_page_signal = any(term in note for term in ("page", "paging", "on-call", "on call"))
    note_ok = has_notification_signal and has_route_signal and has_page_signal
    if norm_label(status) != norm_label("In progress") or norm_label(result) != norm_label("Pending") or not note_ok:
        return {"score": 0, "detail": f"ACT-004 fields are status={status!r}, result={result!r}, routing note present={note_ok}"}
    return {"score": 1, "detail": "ACT-004 is active with pending verification and a routing-defect note"}


def check_workbook_rollup(ws):
    try:
        path = recalc_xlsx(_workbook(ws))
        book = load_workbook(path, data_only=True)
        sheet = book["SLA Summary"]
        actions = load_workbook(_workbook(ws), data_only=True)["Action Register"]
    except Exception as exc:
        return {"score": 0, "detail": f"SLA Summary could not be recalculated/read: {exc}"}
    wanted = {"open": 1, "in progress": 2, "pending verification": 1, "closed": 4, "total corrective actions": 8}
    got = {}
    for row in range(1, sheet.max_row + 1):
        label = norm_label(sheet.cell(row, 1).value)
        if label in wanted:
            got[label] = sheet.cell(row, 2).value
    status_counts = {norm_label(key): 0 for key in wanted if key != "total corrective actions"}
    for row in range(6, actions.max_row + 1):
        status = norm_label(actions.cell(row, 8).value)
        if status in status_counts:
            status_counts[status] += 1
    status_counts[norm_label("total corrective actions")] = sum(status_counts.values())
    if any(status_counts.get(norm_label(key)) != value for key, value in wanted.items()):
        return {"score": 0, "detail": f"action-row counts are {status_counts!r}; cached rollup was {got!r}"}
    return {"score": 1, "detail": "recalculated rollup is 1/2/1/4 with total 8"}


def _digest(value):
    return hashlib.sha256(json.dumps(value, sort_keys=True, default=str, separators=(",", ":")).encode()).hexdigest()


def check_preservation(ws):
    issues = _query(ws, "SELECT * FROM corrective_action_issues WHERE issue_key <> ? ORDER BY issue_key", (ISSUE_KEY,))
    jira_ok = _digest(issues) == JIRA_OTHER_DIGEST
    try:
        book = load_workbook(_workbook(ws), data_only=False)
        sheet = book["Action Register"]
        rows = []
        for row in list(range(6, 9)) + list(range(10, 14)):
            values = []
            for col in range(1, 14):
                value = sheet.cell(row, col).value
                values.append(value.isoformat() if hasattr(value, "isoformat") else value)
            rows.append(values)
        workbook_ok = _digest(rows) == WORKBOOK_OTHER_DIGEST
    except Exception:
        workbook_ok = False
    if not jira_ok or not workbook_ok:
        return {"score": 0, "detail": f"unrelated Jira preserved={jira_ok}, unrelated workbook actions preserved={workbook_ok}"}
    return {"score": 1, "detail": "unrelated Jira issues and workbook actions are unchanged"}
